import hashlib,json,os,re,subprocess

def merge_notes(repo,incoming,approved):
    if incoming!="refs/notes/incoming-validation":raise ValueError("approved incoming reference required")
    env={**os.environ,"GIT_CONFIG_NOSYSTEM":"1","GIT_CONFIG_GLOBAL":os.devnull,"GIT_TERMINAL_PROMPT":"0"}
    def git(*args,check=True):
        r=subprocess.run(["git","-c","user.name=OpsForge private fixture","-c","user.email=fixture@opsforge.invalid","-C",str(repo),*args],env=env,capture_output=True,timeout=5)
        if check and r.returncode:raise RuntimeError(r.stderr.decode("utf8","replace"))
        return r
    def validate(ref):
        for line in git("notes","--ref="+ref,"list").stdout.decode().splitlines():
            note_oid,target=line.split()
            raw=git("cat-file","blob",note_oid).stdout
            if hashlib.sha256(raw).hexdigest() not in approved.get(target,[]):raise ValueError("unapproved note content")
            record=json.loads(raw)
            if set(record)!={"commit","artifact_sha256","status","run_id"} or record["commit"]!=target:
                raise ValueError("record belongs to a different commit")
            if record["status"]!="passed" or not re.fullmatch("[0-9a-f]{64}",record["artifact_sha256"]) or not isinstance(record["run_id"],str) or not record["run_id"]:
                raise ValueError("invalid validation record")
    validate("refs/notes/validation");validate(incoming)
    before=git("rev-parse","--verify","refs/notes/validation").stdout.strip()
    result=git("notes","--ref=validation","merge","-s","manual",incoming,check=False)
    if result.returncode:
        git("notes","--ref=validation","merge","--abort")
        if git("rev-parse","--verify","refs/notes/validation").stdout.strip()!=before:raise RuntimeError("conflicting merge changed approved notes")
        raise ValueError("concurrent notes conflict; explicit reviewed resolution required")
    return git("rev-parse","--verify","refs/notes/validation").stdout.decode().strip()
```

原题知识说明：
交付专用notes引用命名、写入角色、同步refspec和记录格式，明确notes是独立可变引用，不是原提交内容或原提交签名的一部分。客户端默认获取分支并不自动满足所有notes同步需求，需验证所选引用确实往返传输。并发增加记录要选择不会静默覆盖的合并策略，历史重写后的notes复制必须显式配置并说明原新提交映射；复制过来的通过记录不应自动证明新提交已验收。验收两端同时更新、漏同步notes、提交rebase及验证记录撤销，要求界面展示记录对应的准确对象ID和独立信任来源。失败停止用notes作为唯一发布门禁，保留外部不可变验证账本；回退不能删除已经被他人引用的记录来掩盖错误关联。

